// is fully deterministic under test. The original module-level
// Math.random()/Date.now() version is replaced by an OtpService that takes
// Clock and Rng in its constructor; production defaults are exported separately.

export interface Clock {
  now(): number;
}

export interface Rng {
  /** Uniform integer in [0, maxExclusive). */
  int(maxExclusive: number): number;
}

export class SystemClock implements Clock {
  now(): number {
    return Date.now();
  }
}

export class MathRng implements Rng {
  int(maxExclusive: number): number {
    return Math.floor(Math.random() * maxExclusive);
  }
}

export interface Otp {
  code: string;
  expiresAt: number;
}

const CODE_LENGTH = 6;
const TTL_MS = 5 * 60_000;

export class OtpService {
  constructor(
    private readonly clock: Clock = new SystemClock(),
    private readonly rng: Rng = new MathRng(),
  ) {}

  generate(): Otp {
    let code = "";
    for (let i = 0; i < CODE_LENGTH; i++) code += this.rng.int(10);
    return { code, expiresAt: this.clock.now() + TTL_MS };
  }

  verify(stored: Otp, entered: string): boolean {
    return stored.code === entered && this.clock.now() < stored.expiresAt;
  }
}
"})
