result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/otp/otp.test.ts", "content": "import { describe, it, expect } from "vitest";
import { Clock, Rng, OtpService, SystemClock, MathRng } from "./otp";

/** Deterministic clock whose current time can be set/advanced by the test. */
class FixedClock implements Clock {
  constructor(private nowMs: number = 0) {}
  now(): number {
    return this.nowMs;
  }
  advance(ms: number): void {
    this.nowMs += ms;
  }
}

/** Deterministic RNG that replays a scripted sequence of digits. */
class SequenceRng implements Rng {
  private i = 0;
  constructor(private readonly digits: number[]) {}
  int(maxExclusive: number): number {
    if (this.i >= this.digits.length) throw new Error("SequenceRng: script exhausted");
    if (maxExclusive !== 10) throw new Error("SequenceRng only scripts base-10 digits");
    const d = this.digits[this.i++];
    if (!Number.isInteger(d) || d < 0 || d >= maxExclusive)
      throw new Error(`bad scripted digit: ${d}`);
    return d;
  }
}

describe("OtpService with injected fakes", () => {
  it("generates the scripted digits exactly, preserving leading zeros", () => {
    const svc = new OtpService(new FixedClock(), new SequenceRng([0, 0, 7, 3, 2, 9]));
    expect(svc.generate().code).toBe("007329");
  });

  it("verify passes just before expiry (TTL - 1 ms) and fails exactly at expiry", () => {
    const clock = new FixedClock(1_000_000);
    const svc = new OtpService(clock, new SequenceRng([1, 2, 3, 4, 5, 6]));
    const stored = svc.generate(); // expiresAt = 1_000_000 + 300_000

    clock.advance(299_999);
    expect(svc.verify(stored, "123456")).toBe(true);

    clock.advance(1); // exactly at expiry: 300_000 ms elapsed
    expect(svc.verify(stored, "123456")).toBe(false);
  });

  it("rejects a wrong code even when fresh", () => {
    const svc = new OtpService(new FixedClock(), new SequenceRng([1, 2, 3, 4, 5, 6]));
    const stored = svc.generate();
    expect(svc.verify(stored, "654321")).toBe(false);
    expect(svc.verify(stored, "123456")).toBe(true); // sanity: right code works fresh
  });

  it("two generates with different scripted sequences differ", () => {
    const svcA = new OtpService(new FixedClock(), new SequenceRng([1, 1, 1, 1, 1, 1]));
    const svcB = new OtpService(new FixedClock(), new SequenceRng([2, 2, 2, 2, 2, 2]));
    expect(svcA.generate().code).not.toBe(svcB.generate().code);
  });
});

describe("defaults", () => {
  it("property: MathRng-backed codes are always 6 digits", () => {
    const svc = new OtpService(new SystemClock(), new MathRng());
    for (let k = 0; k < 1000; k++) {
      const { code } = svc.generate();
      expect(code).toMatch(/^\d{6}$/);
    }
  });
});
"})
